import React, { useEffect, useMemo } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useIntl } from 'react-intl';
import { getTopHosts } from 'Screens/Contextualization/Dashboard/actions/Actions';
import { selectTop8AssetsByCriticalHigh, selectIsLoadingState, selectTotalAssetsCount } from 'store/Dashboard/selectors';
import { selectCurrentWorkspace } from 'store/Faraday/selectors';
import { redirect } from 'store/Router/actions';
import SpinnerComponent from 'Common/Components/SpinnerContainer';
import colors from 'Styles/colors';
import {
  Wrapper,
  Header,
  HeaderRight,
  Divider,
  RowList,
  AssetRow,
  SeverityBadge,
  AssetName,
  BarTrack,
  BarFill,
  CountText,
  Empty
} from './styled';
import { Title, TitleContainer } from '../common/styled';

const SEVERITY_CONFIG = {
  critical: { label: 'C', color: colors.purple7 },
  high: { label: 'H', color: colors.red6 },
  med: { label: 'M', color: colors.orange5 },
  low: { label: 'L', color: colors.green9 },
  info: { label: 'I', color: colors.blue9 },
  none: { label: '-', color: colors.grey5 }
};

const FindingsByAsset = () => {
  const dispatch = useDispatch();
  const intl = useIntl();

  const topAssets = useSelector(selectTop8AssetsByCriticalHigh);
  const totalCount = useSelector(selectTotalAssetsCount);
  const isLoading = useSelector((state) => selectIsLoadingState(state, 'topAssets'));
  const workspace = useSelector(selectCurrentWorkspace);

  const translations = {
    title: intl.formatMessage({ id: 'dashboard.widgets.findingsByAsset.title' }),
    empty: intl.formatMessage({ id: 'dashboard.widgets.findingsByAsset.empty' })
  };

  useEffect(() => {
    dispatch(getTopHosts());
  }, [dispatch, workspace]);

  const maxCount = useMemo(() => {
    if (!topAssets || topAssets.length === 0) return 1;
    return Math.max(...topAssets.map(a => a.totalCriticalHigh), 1);
  }, [topAssets]);

  const handleAssetClick = (assetId) => {
    dispatch(redirect(`/manage/${workspace}/hosts/${assetId}/vulnerabilities`));
  };

  if (isLoading) return <SpinnerComponent height="250px" />;

  if (!topAssets || topAssets.length === 0) {
    return (
      <Wrapper>
        <Header>
          <TitleContainer>
            <Title>{translations.title}</Title>
          </TitleContainer>
        </Header>
        <Empty>{translations.empty}</Empty>
      </Wrapper>
    );
  }

  const visibleCount = topAssets.length;

  return (
    <Wrapper>
      <Header>
        <TitleContainer>
          <Title>{translations.title}</Title>
        </TitleContainer>
        <HeaderRight>{visibleCount} / {totalCount} visible</HeaderRight>
      </Header>
      <Divider />
      <RowList>
        {topAssets.map((asset) => {
          const config = SEVERITY_CONFIG[asset.highestSeverity] || SEVERITY_CONFIG.none;
          const pct = maxCount > 0 ? (asset.totalCriticalHigh / maxCount) * 100 : 0;
          const displayName = asset.name || asset.ip || `Asset ${asset.id}`;

          return (
            <AssetRow key={ asset.id } onClick={ () => handleAssetClick(asset.id) }>
              <SeverityBadge $color={ config.color }>{config.label}</SeverityBadge>
              <AssetName title={ displayName }>{displayName}</AssetName>
              <BarTrack>
                <BarFill $pct={ pct } $color={ config.color } />
              </BarTrack>
              <CountText>{asset.totalCriticalHigh}</CountText>
            </AssetRow>
          );
        })}
      </RowList>
    </Wrapper>
  );
};

export default FindingsByAsset;
